#!/usr/bin/env bash
# Root wiring job (generated by nmwire.sh; runs on MSI).  Under the lead clone's lock:
# make the lead clone == origin/main@SHA, wire the named modules with wire_orphans.py,
# purge, and build the ROOT target.  Prints the wired import lines on green.
set -u
P=/projects/standard/__MSI_GROUP__/__MSI_USER__
export HOME=$P ELAN_HOME=$P/.elan XDG_CACHE_HOME=$P/.cache PATH=$P/.elan/bin:$PATH
CLONE=__CLONE__; TAG=__TAG__; SHA=__SHA__; MODS="__MODS__"; TARGETS="__TARGETS__"
NMR=$P/nm; PY=$P/params-venv/bin/python3
LOG=$CLONE/.nm/root-$TAG.log
export LEAN_NUM_THREADS=${NT:-8}
summary_fail() { echo "===== SUMMARY"; echo "$1"; exit "${2:-4}"; }
mkdir -p "$CLONE/.nm"
exec 9>"$CLONE/.lake/laneprobe.lock"
flock -w 14400 9 || summary_fail "ROOT FAILED: lead clone lock not free (infra)" 3
exec 8>"$NMR/mirror.lock"; flock -w 900 8 || summary_fail "ROOT FAILED: mirror lock busy"
git -C "$NMR/mirror.git" fetch -q origin 2>/dev/null
exec 8>&-
git -C "$NMR/mirror.git" cat-file -e "$SHA^{commit}" || summary_fail "ROOT FAILED: mirror lacks $SHA"
LAST=$(cat "$CLONE/.nm/base" 2>/dev/null)
if [ -n "$LAST" ] && git -C "$NMR/mirror.git" cat-file -e "$LAST^{commit}" 2>/dev/null; then
  nchg=0
  while IFS= read -r path; do
    [ -n "$path" ] || continue
    if git -C "$NMR/mirror.git" cat-file -e "$SHA:$path" 2>/dev/null; then
      mkdir -p "$CLONE/$(dirname "$path")"
      git -C "$NMR/mirror.git" show "$SHA:$path" > "$CLONE/$path.nmtmp" || summary_fail "ROOT FAILED: delta sync"
      if cmp -s "$CLONE/$path.nmtmp" "$CLONE/$path"; then rm -f "$CLONE/$path.nmtmp"; else mv "$CLONE/$path.nmtmp" "$CLONE/$path"; nchg=$((nchg+1)); fi
    elif [ -e "$CLONE/$path" ]; then rm -f "$CLONE/$path"; nchg=$((nchg+1)); fi
  done < <(git -C "$NMR/mirror.git" diff --name-only --no-renames "$LAST" "$SHA" -- GroupApproximation GroupApproximation.lean scripts)
  echo "[root] delta sync ${LAST:0:9}..${SHA:0:9}: $nchg files" > "$CLONE/.nm/sync-$TAG.txt"
else
  mkdir -p "$NMR/exports"; EXP=$NMR/exports/$SHA
  if [ ! -e "$EXP/.done" ]; then
    exec 8>"$NMR/exports/.lock"; flock -w 1800 8
    if [ ! -e "$EXP/.done" ]; then
      rm -rf "$EXP.tmp"; mkdir -p "$EXP.tmp"
      git -C "$NMR/mirror.git" archive "$SHA" GroupApproximation GroupApproximation.lean scripts | tar -x -C "$EXP.tmp" || summary_fail "ROOT FAILED: export"
      touch "$EXP.tmp/.done"; mv "$EXP.tmp" "$EXP"
    fi
    exec 8>&-
  fi
  rsync -rlc --delete "$EXP/GroupApproximation/" "$CLONE/GroupApproximation/"
  rsync -lc "$EXP/GroupApproximation.lean" "$CLONE/GroupApproximation.lean"
  rsync -rlc --exclude __pycache__ "$EXP/scripts/" "$CLONE/scripts/"
fi
echo "$SHA" > "$CLONE/.nm/base"
cd "$CLONE" || summary_fail "ROOT FAILED: no clone"
cp GroupApproximation.lean ".nm/root-before-$TAG.lean"
if [ -n "$MODS" ]; then
  "$PY" scripts/wire_orphans.py --wire $MODS > "$LOG" 2>&1 || { cat "$LOG"; summary_fail "WIRE REFUSED by wire_orphans.py" 6; }
else
  : > "$LOG"
fi
python3 "$NMR/purge_stale_nm.py" "$CLONE" >> "$LOG" 2>&1
export LAKE_ARTIFACT_CACHE=true LAKE_RESTORE_ARTIFACTS=true LAKE_CACHE_DIR="$NMR/lake-cache"
TS=""; [ -n "${CORES:-}" ] && TS="taskset -c $CORES"
echo "[root] $(hostname -s) threads=$LEAN_NUM_THREADS base=$SHA wire: $MODS extra targets: $TARGETS" >> "$LOG"
timeout 14000 nice -n 5 $TS lake build GroupApproximation $TARGETS >> "$LOG" 2>&1; RC=$?
echo "EXIT=$RC" >> "$LOG"
echo "===== SUMMARY"
echo "host $(hostname -s) base ${SHA:0:9} log $LOG"
grep -n -E '^error|error:|✖' "$LOG" | head -80
echo "--- rebuilt GroupApproximation modules: $(grep -c 'Built GroupApproximation' "$LOG")"
tail -3 "$LOG"
echo "--- wired lines"
diff ".nm/root-before-$TAG.lean" GroupApproximation.lean | grep '^> import' | sed 's/^> //'
if [ $RC -eq 0 ] && grep -q 'Build completed successfully' "$LOG"; then echo "ROOT GREEN"; else echo "ROOT FAILED rc=$RC"; fi
exit $RC
